# Define the helper functions that are available
def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        if inp != out:
            changed.append((i, inp, out))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit from s_in to s_out."""
    # Simple approach: find first differing character position
    pos = None
    old_sub = ""
    new_sub = ""

    # Find first difference
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            pos = i
            break

    # If we found a difference, determine what to replace
    if pos is not None:
        # Check if we're replacing a substring
        # For simplicity, let's assume single character replacement
        old_sub = s_in[pos]
        new_sub = s_out[pos]

        # But we want to be more careful - look at what's really changing
        # Try to find the longest matching prefix/suffix to better understand context
        return (old_sub, new_sub, pos)

    # If strings are same length but no differences found, check if lengths differ
    if len(s_in) != len(s_out):
        # This is a length change case - find the exact change
        if len(s_in) > len(s_out):
            # Deletion
            for i in range(len(s_out)):
                if s_in[i] != s_out[i]:
                    return (s_in[i], "", i)
            return (s_in[len(s_out)], "", len(s_out))
        else:
            # Insertion
            for i in range(len(s_in)):
                if s_in[i] != s_out[i]:
                    return ("", s_out[i], i)
            return ("", s_out[len(s_in)], len(s_in))

    # Strings are identical
    return ("", "", -1)

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates from a transformation."""
    # Simple approach: return the basic replacement that works
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)
    return [(old_sub, new_sub)]

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules match the input/output pairs."""
    predicted = apply_rules(inputs, rules)
    correct = sum(1 for i, o in zip(predicted, outputs) if i == o)
    return correct / len(outputs)

def find_over_applications(inputs, outputs, rules):
    """Find cases where rules incorrectly modify strings that should be unchanged."""
    predicted = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, out, pred) in enumerate(zip(inputs, outputs, predicted)):
        if pred != out and inp != out:  # If prediction is wrong and input was different from output
            over_apps.append((i, inp, pred))
    return over_apps

def simulate_rule_chain(s, rules):
    """Simulate how a string would be transformed by a chain of rules."""
    trace = []
    current = s
    for pattern, replacement in rules:
        prev = current
        current = current.replace(pattern, replacement)
        trace.append({
            'pattern': pattern,
            'replacement': replacement,
            'before': prev,
            'after': current
        })
    return trace

def build_proxy_rules(pattern, replacement, proxy="__X__"):
    """Build pre/post rules to prevent counterfeeding."""
    pre = (pattern, proxy)
    post = (proxy, replacement)
    return (pre, post)

# Now let's work with the actual task
inputs = ['zjibbw', 'eugy', 'hkzghj', 'ywa', 'yagbf']
outputs = ['zjiyyw', 'eagy', 'fdekzgfdej', 'ywa', 'yage']

changed = find_changed_pairs(inputs, outputs)
print("Changed pairs:")
for idx, inp, out in changed:
    print(f"  {idx}: '{inp}' -> '{out}'")

